from torch.utils.cpp_extension import load_inline

# Using a more descriptive name for the library in iteration 3
cuda_source_i3 = """
#include <torch/extension.h>
#include <cuda_runtime.h>

#define TILE_DIM 16

__global__ void matmul_tiled_kernel(const float* a, const float* b, float* out, int N) {
    // Shared memory for tiles of A and B
    __shared__ float a_tile[TILE_DIM][TILE_DIM];
    __shared__ float b_tile[TILE_DIM][TILE_DIM];

    // Thread's position within the block
    int tx = threadIdx.x;
    int ty = threadIdx.y;

    // Block's position within the grid, which corresponds to the C tile
    int block_row = blockIdx.y;
    int block_col = blockIdx.x;

    // The row and column of the C element computed by this thread
    int C_row = block_row * TILE_DIM + ty;
    int C_col = block_col * TILE_DIM + tx;

    float C_value = 0.0f;

    // Loop over the tiles of A and B required to compute the C tile
    for (int t = 0; t < (N + TILE_DIM - 1) / TILE_DIM; ++t) {
        // Collaboratively load tiles into shared memory
        int A_row = C_row;
        int A_col = t * TILE_DIM + tx;
        if (A_row < N && A_col < N) {
            a_tile[ty][tx] = a[A_row * N + A_col];
        } else {
            a_tile[ty][tx] = 0.0f;
        }

        int B_row = t * TILE_DIM + ty;
        int B_col = C_col;
        if (B_row < N && B_col < N) {
            b_tile[ty][tx] = b[B_row * N + B_col];
        } else {
            b_tile[ty][tx] = 0.0f;
        }

        __syncthreads();

        // Compute the dot product for the C element
        for (int k = 0; k < TILE_DIM; ++k) {
            C_value += a_tile[ty][k] * b_tile[k][tx];
        }

        __syncthreads();
    }

    // Write the result to global memory
    if (C_row < N && C_col < N) {
        out[C_row * N + C_col] = C_value;
    }
}

